experiments.source:
header {gq=1,assembly="GRCh38"}
let U=g[1:198600000..198800000]
let R=g[1:198696711..198696909:-]
let A=j[1:198692373..198696711:-]
let B=j[1:198692373..198703297:-]
from @x.records |> within U |> derive {q=any unique {A} & any unique {B}} |> tally {q}

header {gq=1,assembly="GRCh38"}
let U=g[1:198600000..198800000]
let R=g[1:198696711..198696909:-]
let A=j[1:198692373..198696711:-]
let B=j[1:198692373..198703297:-]
from @x.records |> within U |> derive {q=nonempty(unique) & all unique {A | B}} |> tally {q}

header {gq=1,assembly="GRCh38"}
let U=g[1:198600000..198800000]
let R=g[1:198696711..198696909:-]
let A=j[1:198692373..198696711:-]
let B=j[1:198692373..198703297:-]
from @x.records |> within U |> derive {ra=any unique {overlaps(R,min:12bp)},ro=any unique {B},joint=any unique {overlaps(R,min:12bp) & B}} |> tally {ra,ro,joint} by {sample}

header {gq=1,assembly="GRCh38"}
let U=g[1:198600000..198800000]
let R=g[1:198696711..198696909:-]
let A=j[1:198692373..198696711:-]
let B=j[1:198692373..198703297:-]
from @x.records |> within U |> derive {q=any unique {A | B}} |> summarize {n=count(),t=count_true(q),f=count_false(q),u=count_unknown(q),reads=sum(reads.total)} by {sample}

